"""Writes the TrueType font that tests/suite/graphics_fonts.bb loads to check that a font can not make the runtime write outside of memory.

The font has an ascent of 1 unit and a descent of 0, so a font of any height has that many pixels to the unit, and the letter A is a
block that is 1000 units wide and 1000 units tall: 64000 pixels in each direction at a height of 64, which is far more than the picture that
the glyphs of a font are drawn into is wide. A broken font is the only kind that has a letter that is bigger than the text it is in.

Usage: generate_font_limits_fixture.py <output file>
Needs fontTools.
"""
import sys

from fontTools.fontBuilder import FontBuilder
from fontTools.pens.ttGlyphPen import TTGlyphPen

fb = FontBuilder(1000, isTTF=True)
fb.setupGlyphOrder([".notdef", "space", "A"])
fb.setupCharacterMap({32: "space", 65: "A"})

block = TTGlyphPen(None)
block.moveTo((0, 0))
block.lineTo((0, 1000))
block.lineTo((1000, 1000))
block.lineTo((1000, 0))
block.closePath()
empty = TTGlyphPen(None).glyph()
fb.setupGlyf({".notdef": empty, "space": empty, "A": block.glyph()})
fb.setupHorizontalMetrics({".notdef": (500, 0), "space": (500, 0), "A": (1000, 0)})
fb.setupHorizontalHeader(ascent=1, descent=0)
fb.setupNameTable({"familyName": "Limits", "styleName": "Regular"})
fb.setupOS2(sTypoAscender=1, sTypoDescender=0, usWinAscent=1, usWinDescent=0)
fb.setupPost()
fb.save(sys.argv[1])
